{"code":"PAY_PF_ECR","name":"PF — ECR and challan","description":"EPF, EPS and EDLI for the wage month: ECR filed and paid by the 15th of the next month.","category":"other","due_date_category":"STATUTORY_FIXED","service_code":"STREAM_PAYROLL"},
